#include <iostream>
using namespace std;

int main() {
    int n;
    cout << "Enter the starting number = ";
    cin >> n;
    while (n > 0) {
        cout << n << ", ";
        n--;
    }
    cout << "FIRE!!!";
    return 0;
}

char lagi;
do {
    int a, b;
    cout << "Dua bilangan: ";
    cin >> a >> b;
    cout << "Jumlah = " << a + b << endl;
    cout << "Hitung lagi? (y/t): ";
    cin >> lagi;
} while (lagi == 'y' || lagi == 'Y');
cout << "Terima kasih!";

int batas;
do {
    cout << "Masukkan batas (minimal 5): ";
    cin >> batas;
} while (batas < 5);

