#include <iostream>
using namespace std;

int main() {
    int outer = 1;
    while (outer <= 10) {
        int inner = 1;               // direset setiap baris
        while (inner <= outer)
            cout << inner++ << " ";  // cetak dulu, baru naik (postfix)
        cout << endl;
        outer++;
    }
    return 0;
}
